def pick(a):
    if a in OVER: return OVER[a]
    s=(a+' '+M[a]['name']).lower()
    for k,t,rx in PACKS:
        if re.search(rx,s): return k
    return '99-unsorted'
assign={a:pick(a) for a in order}
titles={k:t for k,t,_ in PACKS}; titles['99-unsorted']='Unsorted'
packs={k:[] for k in titles}
for a in order: packs[assign[a]].append(a)
json.dump({'assign':assign,'order':order,'titles':titles},open(os.path.join(OUT,'packs.json'),'w'),indent=1)
for k in titles:
    print(f"## {k} {titles[k]} ({len(packs[k])})")
    for a in packs[k]:
        m=M[a]; print(f"  {a} | {m['name'][:40]} | {'17' if m['has17'] else '--'}{'A' if m['hasAssemblies'] else '-'}")
